CREATE FUNCTION public.pend_submit_checked(_token text,_item uuid,_valor jsonb,_nome text,_config jsonb,_tipo text,_obrigatoria boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.pend_itens; BEGIN SELECT * INTO r FROM public.pend_itens WHERE id=_item FOR UPDATE; IF r.id IS NULL OR r.config IS DISTINCT FROM _config OR r.tipo IS DISTINCT FROM _tipo OR r.obrigatoria IS DISTINCT FROM _obrigatoria THEN RAISE EXCEPTION 'A pergunta mudou. Atualize a página e tente novamente.'; END IF; PERFORM public.pend_submit(_token,_item,_valor,_nome); END; $$;
REVOKE ALL ON FUNCTION public.pend_submit_checked(text,uuid,jsonb,text,jsonb,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pend_submit_checked(text,uuid,jsonb,text,jsonb,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.pend_register_file(_token text,_item uuid,_campo text,_path text,_nome text,_mime text,_tamanho bigint,_autor text,_max integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.pend_itens; n integer; result uuid; cfg jsonb; typ text; part text; field jsonb; cap integer; BEGIN SELECT i.* INTO r FROM public.pend_itens i JOIN public.pend_links l ON l.id=i.link_id WHERE i.id=_item AND l.token=_token AND l.ativo AND (l.expira_em IS NULL OR l.expira_em>now()) FOR UPDATE OF i; IF r.id IS NULL OR r.status='resolvida' THEN RAISE EXCEPTION 'Item indisponível'; END IF; cfg:=r.config; typ:=r.tipo; IF _campo<>'' THEN FOREACH part IN ARRAY string_to_array(_campo,'.') LOOP IF part='anexos' THEN cfg:=cfg->'anexos'; typ:='arquivos'; ELSIF typ='composto' THEN SELECT v INTO field FROM jsonb_array_elements(cfg->'campos') v WHERE v->>'key'=part; cfg:=field; typ:=field->>'tipo'; ELSE RAISE EXCEPTION 'Campo inválido'; END IF; END LOOP; END IF; IF cfg IS NULL OR typ IS DISTINCT FROM 'arquivos' THEN RAISE EXCEPTION 'Campo inválido'; END IF; cap:=COALESCE((cfg->>'maxArquivos')::integer,5); IF cap<1 OR cap>20 OR _tamanho<=0 OR _tamanho>26214400 OR _path NOT LIKE _item::text||'/%' THEN RAISE EXCEPTION 'Arquivo inválido'; END IF; SELECT count(*) INTO n FROM public.pend_arquivos WHERE item_id=_item AND campo_key=_campo; IF n>=cap THEN RAISE EXCEPTION 'Limite de arquivos atingido'; END IF; INSERT INTO public.pend_arquivos(item_id,campo_key,storage_path,nome_original,mime,tamanho,enviado_por_nome) VALUES(_item,_campo,_path,_nome,_mime,_tamanho,_autor) RETURNING id INTO result; RETURN result; END; $$;